create or replace function public.get_integration_access_token(p_integration_id uuid) returns text language sql security definer set search_path='' as $$ select access_token_ciphertext from private.integration_credentials where integration_id=p_integration_id $$;
revoke all on function public.get_integration_access_token(uuid) from public,anon,authenticated;grant execute on function public.get_integration_access_token(uuid) to service_role;
alter table public.integration_events add column if not exists result_id uuid references public.activities(id) on delete set null;
create or replace function public.record_integration_activity(p_integration_id uuid,p_external_id text,p_event_type text,p_payload jsonb,p_description text,p_occurred_at timestamptz) returns uuid language plpgsql security definer set search_path='' as $$ declare owner uuid;result uuid;begin select user_id into owner from public.integrations where id=p_integration_id and status='connected';if owner is null then raise exception 'INTEGRATION_NOT_CONNECTED';end if;select result_id into result from public.integration_events where integration_id=p_integration_id and external_id=p_external_id;if result is not null then return result;end if;insert into public.activities(user_id,description,confidence,occurred_at,idempotency_key) values(owner,left(trim(p_description),500),'integration_verified',coalesce(p_occurred_at,now()),'integration:'||p_integration_id||':'||p_external_id) on conflict(user_id,idempotency_key) do update set description=excluded.description returning id into result;insert into public.integration_events(user_id,integration_id,external_id,event_type,payload,processed_at) values(owner,p_integration_id,p_external_id,p_event_type,p_payload,now()) on conflict(integration_id,external_id) do update set processed_at=coalesce(public.integration_events.processed_at,now()),payload=excluded.payload,result_id=result;return result;end $$;
revoke all on function public.record_integration_activity(uuid,text,text,jsonb,text,timestamptz) from public,anon,authenticated;grant execute on function public.record_integration_activity(uuid,text,text,jsonb,text,timestamptz) to service_role;
